-- Gilneas quests 24681 / 26706. Apply with npc_gilneas_glaive_launcher/vehicle build.
-- Restores matched LoA scene rows (ShatterCore source credited in 2026_10_09_14).
-- No account/character data. Existing scene rows and dialogue win; new GUIDs allocated
-- from each table's maximum so unrelated original-world spawns are never overwritten.
-- Stop worldserver before applying. Private full affected-table backup is required.
START TRANSACTION;
UPDATE creature_template SET npcflag=(npcflag & ~16777216) | 1, AIName='', ScriptName='npc_gilneas_glaive_launcher' WHERE entry=38150;
DELETE FROM npc_spellclick_spells WHERE npc_entry IN (38150,37927,43747);
UPDATE creature_template SET VehicleId=447, faction=80, AIName='', ScriptName='npc_gilneas_glaive_vehicle', spell1=70735,spell2=70732,spell4=59737 WHERE entry=41599;
UPDATE creature_template SET npcflag=(npcflag & ~16777216) | 1, AIName='', ScriptName='npc_hippogryph_endgame' WHERE entry=43747;
UPDATE creature_template SET VehicleId=641, AIName='', ScriptName='npc_hippogryph' WHERE entry=43751;
UPDATE creature_template SET AIName='', ScriptName='npc_tobias_mistmantle_endgame' WHERE entry=43749;
UPDATE creature_template SET AIName='', ScriptName='npc_lorna_crowley_endgame' WHERE entry=43566;
UPDATE creature_template SET VehicleId=983, AIName='', ScriptName='npc_wyvern_endgame' WHERE entry=43713;
DELETE FROM smart_scripts WHERE source_type=0 AND entryorguid=43713;
UPDATE gameobject_template SET ScriptName='go_gilneas_gunship_rope' WHERE entry=204428;
UPDATE creature SET phaseMask=phaseMask | 1048576 WHERE map=654 AND id=38150;
UPDATE creature SET phaseMask=phaseMask | 4194304 WHERE map=654 AND id=43727;
UPDATE creature SET phaseMask=4194304 WHERE map=654 AND id IN (43747,43749);
UPDATE quest_template_addon SET PrevQuestID=24681 WHERE ID=26706 AND PrevQuestID=0;

SET @scene_guid=(SELECT COALESCE(MAX(guid),0) FROM `creature`);

SET @scene_guid=(SELECT COALESCE(MAX(guid),0) FROM `gameobject`);
COMMIT;
